// Where the land is, so the board can print empty land and open sea as different
// faces. The mask is Natural Earth's 1:50m land outline (public domain) at 0.25°,
// generated by pipeline/land.py.

import landUrl from "./land.bin?url";
import { type Grid, NORTH, SOUTH, type View, showsWholeWidth, wrapLon } from "./view";

const PER_DEGREE = 4;
const WIDTH = 360 * PER_DEGREE;
const HEIGHT = (NORTH - SOUTH) * PER_DEGREE;

/** One byte per 0.25° pixel, 1 for land. Row 0 is the north edge, column 0 is 180°W. */
export type Land = Uint8Array;

/** Fetch and unpack the mask. Resolves to an all-sea mask if it can't load, so the map still works. */
export async function loadLand(): Promise<Land> {
	const land = new Uint8Array(WIDTH * HEIGHT);
	try {
		const response = await fetch(landUrl);
		if (!response.ok) throw new Error(`land mask: HTTP ${response.status}`);
		const bytes = new Uint8Array(await response.arrayBuffer());
		// Run lengths as LEB128 varints, alternating sea and land, starting with sea.
		let at = 0;
		let isLand = false;
		for (let i = 0; i < bytes.length; ) {
			let run = 0;
			let shift = 0;
			let byte: number;
			do {
				byte = bytes[i++];
				run |= (byte & 0x7f) << shift;
				shift += 7;
			} while (byte & 0x80);
			if (isLand) land.fill(1, at, at + run);
			at += run;
			isLand = !isLand;
		}
	} catch (e) {
		console.error(e);
	}
	return land;
}

/**
 * Which cells of the board are mostly land, sampling each cell's footprint on the
 * mask. A cell counts as land when at least a third of it is, so thin coasts and
 * islands keep their shape at world zoom without bloating it.
 */
export function landCells(grid: Grid, v: View, land: Land): Uint8Array {
	const out = new Uint8Array(grid.cols * grid.rows);
	// Sample about one point per mask pixel, up to 6x6 per cell.
	const n = Math.max(1, Math.min(6, Math.round(v.dpc * PER_DEGREE)));
	const step = v.dpc / n;
	const whole = showsWholeWidth(grid, v);
	const need = Math.ceil((n * n) / 3);
	for (let row = 0; row < grid.rows; row++) {
		const top = v.lat - (row - grid.rows / 2) * v.dpc;
		for (let col = 0; col < grid.cols; col++) {
			const west = v.lon + (col - grid.cols / 2) * v.dpc;
			// Zoomed out past 360°, the edges would repeat the far side: leave them as sea.
			if (whole && Math.abs(west + v.dpc / 2 - v.lon) > 180) continue;
			let hits = 0;
			for (let sy = 0; sy < n && hits < need; sy++) {
				const lat = top - (sy + 0.5) * step;
				if (lat >= NORTH || lat <= SOUTH) continue;
				const y = Math.floor((NORTH - lat) * PER_DEGREE);
				for (let sx = 0; sx < n; sx++) {
					const lon = wrapLon(west + (sx + 0.5) * step);
					const x = Math.min(WIDTH - 1, Math.floor((lon + 180) * PER_DEGREE));
					if (land[y * WIDTH + x]) hits++;
				}
			}
			if (hits >= need) out[row * grid.cols + col] = 1;
		}
	}
	return out;
}
